// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt
import QtQuick.Controls
import QtQuick.Layouts

// The cart, a compiled-in view. It watches the same live offers the home grid does and
// offers a way back to the storefront. The cart contents are the client's own state in
// version 1; the point of this view is to show a second compiled-in route alongside the
// edge-delivered campaign pages.
Page {
    id: cart

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 16
        spacing: 12

        Label {
            text: "Your cart"
            font.pixelSize: 24
            Layout.fillWidth: true
        }

        ListView {
            Layout.fillWidth: true
            Layout.fillHeight: true
            clip: true
            model: Server.offers
            delegate: ItemDelegate {
                required property string title
                required property int price
                width: ListView.view.width
                text: title + "  -  " + price
            }
        }

        Button {
            text: "Back to the storefront"
            onClicked: Router.go("/")
        }
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt
import QtQuick.Controls
import QtQuick.Layouts

// The storefront home: the product grid, bound to the edge's live `catalog` offers, and a
// button that opens a campaign page. The grid is compiled into the client bundle. The
// campaign page it links to is delivered by the edge (see web/edge/pages/Campaign.qml).
Page {
    id: home

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 16
        spacing: 12

        Label {
            text: "Stall"
            font.pixelSize: 24
            Layout.fillWidth: true
        }

        RowLayout {
            spacing: 8
            Button {
                text: "See today's offers"
                onClicked: Router.go("/c/summer-sale")
            }
            Button {
                text: "Cart"
                onClicked: Router.go("/cart")
            }
        }

        // Updates by itself whenever the edge refills the offers.
        ListView {
            Layout.fillWidth: true
            Layout.fillHeight: true
            clip: true
            model: Server.offers
            delegate: ItemDelegate {
                required property string title
                required property int price
                width: ListView.view.width
                text: title + "  -  " + price
            }
        }
    }
}

