// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

// The seed for /c/:campaign, run on the edge after the page's scope check. It turns the
// campaign slug into the headline the page paints on its first frame, so the page never
// flashes empty while the catalog replica arrives, and every campaign gets its own seed
// even though one Campaign.qml serves them all. Whatever this returns is public output.
import SynQt

PageSeed {
    // The parameters are left untyped because the edge invokes this hook generically,
    // passing every argument as a QVariant, so annotating a parameter with a concrete type
    // (route, string) would change the QML method signature to seedFor(QString, ...) and the
    // edge's QVariant call would no longer match it, silently seeding nothing. The return is
    // annotated var, which does match, because a seed is a JS object literal.
    function seedFor(route, parameters, caller): var {
        const slug = parameters.campaign ?? "";
        const words = slug.split("-").filter(part => part.length > 0);
        const headline = words
            .map(part => part.charAt(0).toUpperCase() + part.slice(1))
            .join(" ");
        return { headline: headline.length > 0 ? headline : "Today's offers" };
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import QtQuick
import QtQuick.Layouts

// The campaign page the edge delivers for "/c/:campaign". One file serves every slug: it
// paints its headline from the per-request seed the edge built (Router.pageSeed), so it
// shows real content on its first frame, before the catalog replica has pushed anything,
// and never flashes empty. Once the offers arrive it keeps them live through
// Server.offers. It may import only the palette modules (QtQuick, QtQuick.Layouts);
// the client's QmlPalette refuses any other. The root is an Item, because a delivered page
// is loaded into the client's Loader, not shown as a window of its own.
Item {
    id: campaign

    readonly property string headline: Router.pageSeed.headline ?? "Today's offers"

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 16
        spacing: 12

        Text {
            text: campaign.headline
            font.pixelSize: 24
            Layout.fillWidth: true
            wrapMode: Text.WordWrap
        }

        ListView {
            Layout.fillWidth: true
            Layout.fillHeight: true
            clip: true
            model: Server.offers
            delegate: Text {
                required property string title
                required property int price
                width: ListView.view.width
                text: title + "  -  " + price
            }
        }
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import QtQuick
import QtQuick.Layouts

// The members-only page the edge delivers for "/members". Its route declares `scope: user`,
// so the edge refuses to deliver a single byte of it to an under-scoped session: an
// anonymous fetch comes back "forbidden" with no markup, no hash, and no seed, and this
// file is never sent. It imports only the palette modules and its root is an Item, like
// every delivered page. It carries no seed. There is nothing secret to paint before the
// connect points arrive.
Item {
    id: members

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 16
        spacing: 12

        Text {
            text: "Members only"
            font.pixelSize: 24
            Layout.fillWidth: true
        }

        Text {
            text: "Thanks for signing in. Your member offers live here."
            Layout.fillWidth: true
            wrapMode: Text.WordWrap
        }
    }
}

